// A paced, prescribed root rotation of ONE already recovered petal. No elastic dynamics or storage transition.
function createPetalSequence(){
 let timeS=30,playing=false,totalDurationS=30;
 const getState=()=>{const q=clamp(timeS/totalDurationS),opening=q*q*(3-2*q);return{timeS,totalDurationS,playing,opening,phase:q===0?'ready':q===1?'open':'moving',scope:'one-recovered-petal',compactionSolved:false};};
 return{getState,play(){playing=timeS<totalDurationS;return getState();},pause(){playing=false;return getState();},reset(){timeS=0;playing=false;return getState();},seek(t){timeS=clamp(Number(t)||0,0,totalDurationS);if(timeS===totalDurationS)playing=false;return getState();},update(dt){if(playing&&Number.isFinite(dt)&&dt>0){timeS=Math.min(totalDurationS,timeS+dt);if(timeS===totalDurationS)playing=false;}return getState();},setDurations({openingDurationS}={}){const q=timeS/totalDurationS;totalDurationS=clamp(Number(openingDurationS)||30,10,90);timeS=q*totalDurationS;return getState();},getDurations:()=>({openingDurationS:totalDurationS})};
}
