 if(stageOnly){for(const code of['COR','ARO','PET','TAL','HOJ','RAI','CTL','ANT','ELEV','EXC'])if(g[code])g[code].visible=false;model.stageTrap.root.visible=state.showStage;return;}
 if(state.view==='folded'){for(const code of['TAL','HOJ','RAI','CTL','ANT'])if(g[code])g[code].visible=false;}
 if(detail){model.stageTrap.root.visible=false;g.ELEV.visible=false;g.EXC.visible=state.showKeepout&&state.view==='stem';}
 if(isLab()){g.TAL.visible=false;g.HOJ.visible=false;}
 else if(state.view==='stem'||state.view==='leaves'){for(const code of['PET','ARO','RAI','CTL','ANT'])if(g[code])g[code].visible=false;if(state.view==='leaves')for(const child of g.TAL.children)if(child.name.includes('Manga')||child.name.includes('Franja'))child.visible=false;}
