function measuredInputs(){const read=id=>{const t=$('#'+id)?.value?.trim();return t===''||t==null?null:Number.isFinite(Number(t))?Number(t):null;};return{massKg:read('mass-kg'),cgRadialM:read('cg-z'),cgHeightM:read('cg-y'),basis:'CG medido respecto a raíz, pétalo horizontal; eje transversal no afecta este momento.'};}
function restoreMeasuredInputs(v){for(const[id,key]of[['mass-kg','massKg'],['cg-z','cgRadialM'],['cg-y','cgHeightM']])$('#'+id).value=Number.isFinite(v[key])?v[key]:'';}
function updateGravity(){
 const x=measuredInputs();let pm=metrics?.petalMechanism;gravityCase=null;
 const pending='Par de gravedad separado del accionamiento: la tensión de los tres cabos queda pendiente de roldanas tangentes, bobinado apoyado, retractor/freno y reparto de cargas. El recorrido dibujado no valida la transmisión de fuerzas.';
 $('#rope-case').textContent=pending;
 if(!pm?.rootM||!pm.axisM||!Number.isFinite(x.massKg)||x.massKg<=0||!Number.isFinite(x.cgRadialM)||!Number.isFinite(x.cgHeightM)){$('#gravity-torque').textContent='—';$('#gravity-input-status').textContent='Falta masa y centro de masa medidos del conjunto móvil. No se asignan valores por su apariencia.';return;}
 try{
  pm=model.getMetrics().petalMechanism;const a=pm.rootAzimuthDeg*Math.PI/180,rest=pm.rootM.map((v,k)=>v+(k===0?x.cgRadialM*Math.sin(a):k===1?x.cgHeightM:x.cgRadialM*Math.cos(a))),com=rotateAroundAxis(rest,pm.rootM,pm.axisM,-pm.angleDeg*Math.PI/180);
  const ideal=evaluateHingeEquilibrium({axis:pm.axisM,root:pm.rootM,com,massKg:x.massKg,attachment:pm.attachmentM,guide:pm.guideM});
  // Only the gravity moment is applicable. A bend inside a void and an unsupported
  // helix supply no measured contact reaction, so no public tension is inferred.
  gravityCase={scope:'quasi-static-gravity-moment-only',massKnown:ideal.massKnown,massKg:ideal.massKg,gravityTorquePerKgNm:ideal.gravityTorquePerKgNm,gravityTorqueNm:ideal.gravityTorqueNm,measuredInputs:x,comWorldM:com,tensionN:null,feasibleWithTension:null,forceRoutingValidated:false,physicalTensionPrediction:false,status:'actuation-force-route-unresolved',requiredPhysicalChecks:['Roldana con garganta y dos tangentes; arco de apoyo real del cabo.','Bobinado apoyado sobre el tambor y fijación real del extremo.','Retractor, freno y transmisión de mando seleccionados y medidos.','Reparto de cargas entre los tres cabos y toma de carga final.'],meaning:'El par del peso no valida el supuesto apoyo de las guías o los carretes dibujados.'};
  $('#gravity-torque').textContent=Number.isFinite(gravityCase.gravityTorqueNm)?fmt(gravityCase.gravityTorqueNm,2)+' N·m':'—';$('#gravity-input-status').textContent='Par calculado con los valores introducidos; no es una validación de las líneas o del accionamiento.';
 }catch(error){$('#gravity-torque').textContent='—';$('#gravity-input-status').textContent='No se pudo calcular el par con estos datos: '+error.message;}
}
