 $('#contact-state').textContent=!bench?'Vista de referencia; su movimiento no está comprobado':blocked?'Petición detenida':q?.verified&&q?.geometryClear?'Estado libre en el alcance declarado':q?.geometryClear?'Geometría libre; cobertura incompleta':q?'Contacto o comprobación pendiente':'Comprobación pendiente';
