 $('#contact-gap-label').textContent=detail?.conservativeEnclosurePair?'Distancia de envolventes conservadoras':blocked?'Distancia consultada de la petición':'Distancia entre superficies';const gap=detail?.rawGapM??detail?.physicalGapM??detail?.gapM;$('#contact-gap').textContent=bench&&Number.isFinite(gap)?fmt(gap*1000,2)+' mm':'—';$('#contact-reserve').textContent=Number.isFinite(detail?.requiredMarginM)?fmt(detail.requiredMarginM*1000,2)+' mm':fmt(CONTACT_MARGIN_M*1000,2)+' mm propuesta';$('#contact-badge').textContent=$('#contact-state').textContent;
 const currentGap=q?.rawGapM??q?.physicalGapM??q?.gapM;$('#contact-current').textContent=bench?'Estado conservado a '+fmt((config.petalRootReadyDeg??70)*(1-committedOpening),2)+'°'+(Number.isFinite(currentGap)?' · distancia actual mínima '+fmt(currentGap*1000,2)+' mm.':'. Comprobación actual sin resolver.'):'Vista de referencia distinta del banco de contacto.';
