function restoreSharedView(){
 try{const raw=new URLSearchParams(location.hash.slice(1)).get('vista');if(!raw)return false;const saved=JSON.parse(raw);if(saved.revision!=='F04'||!saved.state)return false;const candidate={...state},ranges={opening:[0,1],speed:[0,12],azimuth:[0,360],gust:[1,1.8],packHeightM:[.1,.6],chamberTopM:[2,3],deckThicknessM:[0,.3],slopeDeg:[10,15]};for(const[key,range]of Object.entries(ranges))if(Number.isFinite(saved.state[key]))candidate[key]=clamp(saved.state[key],...range);for(const key of['showSkin','showMachine','showStage','cutaway','showKeepout','colors','showRopes'])if(typeof saved.state[key]==='boolean')candidate[key]=saved.state[key];if(Object.hasOwn(explanations,saved.state.view))candidate.view=saved.state.view;candidate.stemMode=saved.state.stemMode==='strips'?'strips':'continuous';candidate.packMode='organic';if(candidate.liftProgress>0)candidate.trapProgress=1;Object.assign(state,candidate);state.windOn=false;state.leafProgress=1;if(['folded','stage','trap'].includes(state.view)){state.liftProgress=0;state.trapProgress=state.view==='trap'?1:0;}else{state.liftProgress=1;state.trapProgress=1;}manual=true;seq.pause();frozen=!!saved.frozen;labels=!!saved.labels;cotas=!!saved.cotas;playbackRate=[.5,1,2].includes(saved.playbackRate)?saved.playbackRate:1;if(Number.isFinite(saved.sequence?.durations?.openingDurationS))seq.setDurations(saved.sequence.durations);if(Number.isFinite(saved.sequence?.timeS))seq.seek(saved.sequence.timeS);if(saved.comparison){for(const[id,key,min,max]of[['density','densityKgM3',.75,1.3],['cd','cd',.2,3],['extra-allowance','extraAllowanceM',0,.3]])if(Number.isFinite(saved.comparison[key]))$('#'+id).value=clamp(saved.comparison[key],min,max);}$('#chamber-height').value=String(state.chamberTopM);$('#deck-thickness').value=state.deckThicknessM;$('#playback-rate').value=playbackRate;$('#open-duration').value=seq.getDurations().openingDurationS;if(saved.measuredInputs)restoreMeasuredInputs(saved.measuredInputs);applyModel();syncSequence();updateUI();updateMetrics();rebuildLabels();rebuildDimensions();const array=a=>Array.isArray(a)&&a.length===3&&a.every(v=>Number.isFinite(v)&&Math.abs(v)<200);if(array(saved.camera)&&array(saved.target)){tween=null;camera.position.copy(V(saved.camera));controls.target.copy(V(saved.target));}else fit();return true;}catch{return false;}
}

function canvasTexture(kind){const c=document.createElement('canvas');c.width=c.height=512;const x=c.getContext('2d');let seed=14;const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};x.fillStyle=kind==='leaf'?'#66866a':'#6b9c91';x.fillRect(0,0,512,512);for(let i=0;i<1800;i++){const xx=rand()*512,yy=rand()*512;x.strokeStyle=`rgba(${kind==='leaf'?'206,215,157':'210,227,186'},${.02+rand()*.12})`;x.lineWidth=.4+rand()*1.5;x.beginPath();x.moveTo(xx,yy);x.lineTo(xx+rand()*12,yy+25+rand()*150);x.stroke();}if(kind==='leaf'){x.strokeStyle='#bec795';x.lineWidth=4;x.beginPath();x.moveTo(256,512);x.quadraticCurveTo(244,210,256,0);x.stroke();x.lineWidth=2;for(let i=1;i<8;i++)for(const side of[-1,1]){const y=i*60;x.beginPath();x.moveTo(256,y+100);x.quadraticCurveTo(256+side*65,y+20,256+side*(180-Math.abs(4-i)*16),y-20);x.stroke();}}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t;}

function resize(){const r=$('#viewport').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();projectLabels();}

function frame(t){
 requestAnimationFrame(frame);const dt=lastTime?Math.min(.25,(t-lastTime)/1000):0;lastTime=t;if(!frozen)simTime+=dt;
 if(t-lastGeometry>=100){
  const step=(t-lastGeometry)/1000;lastGeometry=t;
  if(trapDemoStart!==null&&!frozen){state.trapProgress=clamp((simTime-trapDemoStart)/8);if(state.trapProgress===1)trapDemoStart=null;applyModel();updateUI({animate:true});studio.invalidate();}
  if(!manual&&!frozen&&isLab()&&seq.getState().playing){const desired=seq.update(Math.min(.3,step)*playbackRate).opening;requestOpening(desired,{source:'cadencia de giro',notifyOnBlock:true});applyModel();updateUI({animate:true});updateContactUI();if(cotas)rebuildDimensions();studio.invalidate();}
 }
 if(t-lastMetrics>600){updateMetrics();lastMetrics=t;}
 if(tween){const k=clamp((t-tween.start)/500),v=k*k*(3-2*k);camera.position.lerpVectors(tween.from,tween.to,v);controls.target.lerpVectors(tween.fromTarget,tween.target,v);if(k===1)tween=null;}controls.update();studio.update();if(t-lastLabel>70){projectLabels();lastLabel=t;}renderer.render(scene,camera);
}

